// loadOrder eagerly loads the "order" edge for the given nodes.
func (q *OrderItemQuery) loadOrder(ctx context.Context, query *OrderQuery, nodes []*entity.OrderItem, init func(*entity.OrderItem), assign func(*entity.OrderItem, *entity.Order)) error {
	query = query.clone()
	fkSeen := make(map[int]struct{}, len(nodes))
	var fks []any
	for _, n := range nodes {
		fkRaw := n.FKValue("order_items")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if _, ok := fkSeen[fkVal]; !ok {
			fkSeen[fkVal] = struct{}{}
			fks = append(fks, any(fkVal))
		}
		if init != nil {
			init(n)
		}
	}
	if len(fks) == 0 {
		return nil
	}
	query.Where(func(s *sql.Selector) {
		s.Where(sql.In(s.C(order.FieldID), fks...))
	})
	neighbors, err := query.All(ctx)
	if err != nil {
		return err
	}
	neighborByID := make(map[int]*entity.Order, len(neighbors))
	for _, n := range neighbors {
		neighborByID[n.ID] = n
	}
	for _, n := range nodes {
		fkRaw := n.FKValue("order_items")
		if fkRaw == nil {
			continue
		}
		fkVal := derefFK(fkRaw).(int)
		if neighbor, ok := neighborByID[fkVal]; ok {
			assign(n, neighbor)
		}
	}
	return nil
}

